const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{box-sizing:border-box;width:100%;height:100%;display:flex;flex-direction:column;padding:12px;color:var(--ink);background:transparent;font:13px/1.35 system-ui,-apple-system,\"PingFang SC\",\"Microsoft YaHei\",sans-serif;overflow:hidden}\n.card *{box-sizing:border-box}\n.card[data-size=\"3x3\"]{padding:8px}\n.card[data-size=\"3x6\"],.card[data-size=\"6x6\"]{padding:14px}\n.pane{flex:1;min-height:0;min-width:0;display:flex;flex-direction:column;gap:8px}\n.card[data-size=\"3x3\"] .pane{gap:6px}\n.hd{flex:none;display:flex;align-items:center;gap:6px;min-width:0}\n.ttl{flex:1;min-width:0;font-weight:700;font-size:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.card[data-size=\"3x3\"] .ttl{font-size:13px}\n.badge{flex:none;font-size:11px;line-height:1;padding:4px 8px;border-radius:999px;background:var(--accent);color:var(--on-accent);white-space:nowrap}\n.card[data-size=\"3x3\"] .badge{padding:4px 6px;font-size:10.5px}\n.badge.ok{background:var(--soft);color:var(--muted)}\n.card[data-size^=\"3\"] .badge.ok{display:none}\n.btn{flex:none;display:inline-flex;align-items:center;justify-content:center;gap:3px;min-height:30px;padding:0 12px;border:1px solid var(--line);border-radius:9px;background:var(--button-paper,var(--panel-paper));color:var(--ink);font:inherit;font-size:12.5px;white-space:nowrap;cursor:pointer}\n.btn.pri{background:var(--accent);color:var(--on-accent);border-color:transparent;font-weight:600}\n.btn:disabled,.step:disabled{opacity:.45;cursor:default}\n.btn:focus-visible,.step:focus-visible,.chip:focus-visible,.main:focus-visible,.inp:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n.btn.ico{width:30px;padding:0;font-size:15px}\n.add .plus{font-size:17px;line-height:1}\n.card[data-size^=\"3\"] .add{width:30px;padding:0}\n.card[data-size^=\"3\"] .add .lbl{display:none}\n.err{flex:none;padding:5px 8px;border-radius:8px;border:1px solid var(--accent);background:var(--soft);color:var(--ink);font-size:12px;font-weight:600}\n.hide{display:none}\n\n.list{flex:1;min-height:0;overflow-y:auto;display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,170px),1fr));grid-auto-rows:min-content;align-content:start;gap:6px;padding-right:2px}\n.row{display:flex;align-items:center;gap:6px;min-width:0;padding:6px 6px 6px 10px;border:1px solid var(--line);border-radius:11px;background:var(--panel-paper)}\n.row.low{background:var(--soft);border-color:var(--accent);box-shadow:inset 4px 0 0 var(--accent)}\n.card[data-size=\"3x3\"] .row{padding:5px 5px 5px 9px;gap:4px}\n.main{flex:1;min-width:0;display:flex;flex-direction:column;gap:2px;padding:0;border:0;background:none;color:inherit;font:inherit;text-align:left;cursor:pointer}\n.nm{display:block;min-width:0;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-weight:600;font-size:13px}\n.l2{display:flex;flex-wrap:wrap;align-items:center;gap:2px 6px;min-width:0}\n.qt{display:inline-flex;align-items:baseline;gap:3px;font-variant-numeric:tabular-nums;white-space:nowrap}\n.qt b{font-size:18px;line-height:1.1}\n.qt i{font-style:normal;font-size:11px;color:var(--muted)}\n.tag{flex:none;font-size:10px;line-height:1;padding:3px 6px;border-radius:999px;background:var(--accent);color:var(--on-accent);white-space:nowrap}\n.hint{display:none;font-size:11px;color:var(--muted)}\n.card[data-size=\"3x6\"] .hint,.card[data-size=\"6x6\"] .hint{display:block}\n.card[data-size=\"3x6\"] .row,.card[data-size=\"6x6\"] .row{padding:9px 8px 9px 12px}\n.card[data-size=\"6x6\"] .qt b{font-size:22px}\n.ctl{flex:none;display:flex;gap:4px}\n.step{width:30px;height:30px;padding:0;border-radius:50%;border:1px solid var(--line);background:var(--button-paper,var(--panel-paper));color:var(--ink);font:inherit;font-size:18px;line-height:1;cursor:pointer}\n.step.plus{background:var(--accent);color:var(--on-accent);border-color:transparent}\n.card[data-size=\"3x3\"] .step{width:27px;height:27px;font-size:16px}\n.card[data-size=\"3x3\"] .ctl{gap:3px}\n\n.empty{flex:1;min-height:0;overflow-y:auto;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:10px;text-align:center;color:var(--muted)}\n.etx{font-size:12px;max-width:300px}\n.chips{display:flex;flex-wrap:wrap;gap:6px}\n.empty .chips{justify-content:center}\n.chip{min-height:28px;padding:0 10px;border:1px solid var(--line);border-radius:999px;background:var(--button-paper,var(--panel-paper));color:var(--ink);font:inherit;font-size:12px;cursor:pointer}\n.card[data-size=\"3x3\"] .chip{padding:0 8px}\n\n.scroll{flex:1;min-height:0;min-width:0;overflow-y:auto;display:flex;flex-direction:column;gap:8px;padding-right:2px}\n.fgrid{display:grid;grid-template-columns:1fr 1fr;gap:8px}\n.fld{display:flex;flex-direction:column;gap:3px;min-width:0}\n.fl{font-size:11px;color:var(--muted)}\n.inp{width:100%;min-width:0;height:30px;padding:0 8px;border:1px solid var(--line);border-radius:8px;background:var(--paper);color:var(--ink);font:inherit;font-size:13px}\n.f-name,.f-low,.f-uchips,.f-nchips{grid-column:1/-1}\n.card[data-size^=\"6\"] .fgrid{grid-template-columns:2fr 1fr 1fr}\n.card[data-size^=\"6\"] .f-name{grid-column:auto}\n.card[data-size^=\"6\"] .f-low{grid-column:1}\n.card[data-size^=\"6\"] .f-uchips{grid-column:2/-1;justify-content:flex-end}\n.card[data-size^=\"6\"] .f-nchips{grid-column:1/-1}\n.ft{flex:none;display:flex;gap:8px}\n.ft .btn{flex:1}\n.ft.wrap{flex-wrap:wrap}\n.ask{flex-basis:100%;font-size:12px;font-weight:600}\n\n.dbody{flex:1;min-height:0;min-width:0;overflow-y:auto;display:flex;flex-direction:column;gap:10px;padding-right:2px}\n.card[data-size^=\"6\"] .dbody{display:grid;grid-template-columns:1fr 1fr;gap:14px;align-content:start}\n.dq{display:flex;flex-direction:column;gap:4px;min-width:0}\n.big{display:flex;flex-wrap:wrap;align-items:baseline;gap:4px 6px;font-variant-numeric:tabular-nums}\n.big b{font-size:30px;line-height:1.1}\n.card[data-size=\"6x6\"] .big b,.card[data-size=\"3x6\"] .big b{font-size:44px}\n.big i{font-style:normal;font-size:14px;color:var(--muted)}\n.st{font-size:12px;color:var(--muted)}\n.st.low{color:var(--ink);font-weight:700}\n.da{display:flex;flex-direction:column;gap:8px;min-width:0}\n.two{display:grid;grid-template-columns:1fr 1fr;gap:8px}\n.two .btn{min-height:34px}\n.note{min-height:16px;font-size:12px;color:var(--muted)}\n.note.bad{color:var(--ink);font-weight:700}\n";
function bsR(n){return Math.round(n*100)/100}
function bsFmt(n){return String(bsR(Number(n)||0))}
function bsItems(s){return s&&Array.isArray(s.items)?s.items:[]}
function bsLow(i){return typeof i.low==='number'&&isFinite(i.low)&&i.qty<i.low}
function bsSort(list){return list.filter(bsLow).concat(list.filter(function(i){return !bsLow(i)}))}
function bsWith(s,fn){return Object.assign({},s,{items:fn(bsItems(s))})}
function bsNum(v){var t=String(v==null?'':v).trim();if(t==='')return NaN;var n=Number(t);return isFinite(n)?n:NaN}
function bsFind(c,id){return bsItems(c.state).find(function(i){return i.id===id})}

function bsAdjust(c,id,delta){
  const {update,ui,redraw}=c;
  ui.err='';
  update(function(s){return bsWith(s,function(l){return l.map(function(i){return i.id===id?Object.assign({},i,{qty:Math.max(0,bsR(i.qty+delta))}):i})})}).catch(function(){ui.err='保存失败，数量没有改变，请重试';redraw();});
}

function bsOpenForm(c,it,name){
  const {ui,redraw}=c;
  ui.view='form';ui.editId=it?it.id:null;ui.err='';
  ui.draft=it?{name:it.name,qty:bsFmt(it.qty),unit:it.unit||'',low:bsFmt(it.low)}:{name:name||'',qty:'',unit:'',low:''};
  redraw();
}

function bsOpenDetail(c,id){
  const {ui,redraw}=c;
  ui.view='detail';ui.detailId=id;ui.note='';ui.noteBad=false;ui.amount='1';ui.confirmDel=false;ui.err='';
  redraw();
}

function mount(ctx){
  const {root,ui}=ctx;
  if(ui.view==='form')root.appendChild(bsForm(ctx));
  else if(ui.view==='detail'&&bsFind(ctx,ui.detailId))root.appendChild(bsDetail(ctx));
  else{ui.view='list';root.appendChild(bsList(ctx));}
}

function bsList(c){
  const {el,state,ui}=c;
  const items=bsSort(bsItems(state));
  const lowN=items.filter(bsLow).length;
  const kids=[el('div',{class:'ttl',title:'宝宝用品库存'},'宝宝用品库存')];
  if(lowN)kids.push(el('span',{class:'badge'},'快用完 '+lowN));
  else if(items.length)kids.push(el('span',{class:'badge ok'},'共 '+items.length+' 样，都够用'));
  kids.push(el('button',{class:'btn pri add',type:'button','aria-label':'添加用品',onclick:function(){bsOpenForm(c,null,'')}},el('span',{class:'plus'},'+'),el('span',{class:'lbl'},'添加')));
  const parts=[el('div',{class:'hd'},...kids)];
  if(ui.err)parts.push(el('div',{class:'err',role:'alert'},'⚠ '+ui.err));
  parts.push(items.length?el('div',{class:'list'},...items.map(function(it){return bsRow(c,it)})):bsEmpty(c));
  return el('div',{class:'pane'},...parts);
}

function bsRow(c,it){
  const {el}=c;
  const low=bsLow(it),u=it.unit||'';
  const q=[el('b',{},bsFmt(it.qty))];
  if(u)q.push(el('i',{},u));
  const line2=[el('span',{class:'qt'},...q)];
  if(low)line2.push(el('span',{class:'tag'},'快用完'));
  const main=el('button',{class:'main',type:'button','aria-label':it.name+'，剩 '+bsFmt(it.qty)+u+(low?'，快用完':'')+'，打开详情',onclick:function(){bsOpenDetail(c,it.id)}},
    el('span',{class:'nm',title:it.name},it.name),
    el('span',{class:'l2'},...line2),
    el('span',{class:'hint'},'低于 '+bsFmt(it.low)+u+' 时提醒'));
  const ctl=el('div',{class:'ctl'},
    el('button',{class:'step',type:'button','aria-label':it.name+' 用掉 1',title:'用掉 1',disabled:it.qty<=0,onclick:function(){bsAdjust(c,it.id,-1)}},'−'),
    el('button',{class:'step plus',type:'button','aria-label':it.name+' 买来 1',title:'买来 1',onclick:function(){bsAdjust(c,it.id,1)}},'+'));
  return el('div',{class:'row'+(low?' low':'')},main,ctl);
}

function bsEmpty(c){
  const {el}=c;
  return el('div',{class:'empty'},
    el('div',{class:'etx'},'还没有记录。点下面的名字快速添加，再填剩余数量和单位。'),
    el('div',{class:'chips'},...['尿不湿','奶粉','湿巾'].map(function(n){return el('button',{class:'chip',type:'button',onclick:function(){bsOpenForm(c,null,n)}},'+ '+n)})));
}


function bsForm(c){
  const {el,ui,uid,commit,redraw}=c;
  const d=ui.draft||(ui.draft={name:'',qty:'',unit:'',low:''});
  const editing=!!ui.editId;
  let busy=false;
  const errBox=el('div',{class:'err hide',role:'alert'});
  const showErr=function(m){errBox.textContent='⚠ '+m;errBox.className='err';};
  const cancel=function(){ui.view=editing?'detail':'list';ui.draft=null;redraw();};
  const onEnter=function(e){if(e.key==='Enter'){e.preventDefault();save();}};

  const nameInp=el('input',{class:'inp',type:'text',value:d.name,placeholder:'例如：尿不湿','aria-label':'名称',oninput:function(e){d.name=e.target.value},onkeydown:onEnter});
  const qtyInp=el('input',{class:'inp',type:'number',min:'0',step:'any',inputmode:'decimal',value:d.qty,placeholder:'0','aria-label':'剩余数量',oninput:function(e){d.qty=e.target.value},onkeydown:onEnter});
  const unitInp=el('input',{class:'inp',type:'text',value:d.unit,placeholder:'包/罐/片','aria-label':'单位',oninput:function(e){d.unit=e.target.value},onkeydown:onEnter});
  const lowInp=el('input',{class:'inp',type:'number',min:'0',step:'any',inputmode:'decimal',value:d.low,placeholder:'低于它就提醒','aria-label':'快用完数量',oninput:function(e){d.low=e.target.value},onkeydown:onEnter});

  const fld=function(cls,label,inp){return el('label',{class:'fld '+cls},el('span',{class:'fl'},label),inp)};
  const chipRow=function(cls,label,opts,pick){
    return el('div',{class:'fld '+cls},el('span',{class:'fl'},label),
      el('div',{class:'chips'},...opts.map(function(o){return el('button',{class:'chip',type:'button',onclick:function(){pick(o)}},o)})));
  };
  const uchips=chipRow('f-uchips','常用单位',['片','包','罐','袋','盒','g'],function(u){d.unit=u;unitInp.value=u;});
  const cells=[fld('f-name','名称',nameInp),fld('f-qty','剩余数量',qtyInp),fld('f-unit','单位',unitInp),fld('f-low','快用完数量',lowInp),uchips];
  if(!editing)cells.push(chipRow('f-nchips','常用物品',['尿不湿','奶粉','湿巾'],function(n){d.name=n;nameInp.value=n;}));

  const saveBtn=el('button',{class:'btn pri',type:'button',onclick:function(){save()}},editing?'保存修改':'保存');
  function save(){
    if(busy)return;
    const name=String(d.name||'').trim(),qty=bsNum(d.qty),low=bsNum(d.low);
    if(!name){showErr('请填写名称');return;}
    if(!(qty>=0)){showErr('请填写剩余数量，需为不小于 0 的数字');return;}
    if(!(low>=0)){showErr('请填写快用完数量，剩余低于它就会排到前面');return;}
    const unit=String(d.unit||'').trim(),id=ui.editId,nid=id||uid();
    busy=true;saveBtn.disabled=true;
    commit(function(s){
      return bsWith(s,function(list){
        if(id)return list.map(function(i){return i.id===id?Object.assign({},i,{name:name,qty:bsR(qty),unit:unit,low:bsR(low)}):i});
        return list.concat([{id:nid,name:name,qty:bsR(qty),unit:unit,low:bsR(low)}]);
      });
    },{view:id?'detail':'list',detailId:id||null,editId:null,draft:null,amount:'1',note:'',noteBad:false,confirmDel:false,err:''}).catch(function(){
      busy=false;saveBtn.disabled=false;showErr('保存失败，请重试');
    });
  }

  return el('div',{class:'pane form'},
    el('div',{class:'hd'},el('button',{class:'btn ico',type:'button','aria-label':'返回',onclick:cancel},'←'),el('div',{class:'ttl'},editing?'编辑用品':'添加用品')),
    el('div',{class:'scroll'},errBox,el('div',{class:'fgrid'},...cells)),
    el('div',{class:'ft'},el('button',{class:'btn',type:'button',onclick:cancel},'取消'),saveBtn));
}


function bsDetail(c){
  const {el,ui,update,redraw}=c;
  const it=bsFind(c,ui.detailId),low=bsLow(it),u=it.unit||'';
  if(ui.amount==null)ui.amount='1';
  const back=function(){ui.view='list';ui.detailId=null;ui.note='';ui.confirmDel=false;redraw();};

  const apply=function(sign){
    const a=bsNum(ui.amount);
    if(!(a>0)){ui.note='请填写大于 0 的数量';ui.noteBad=true;redraw();return;}
    const before=it.qty;
    ui.noteBad=false;
    ui.note=sign<0?(a>before?'只剩 '+bsFmt(before)+u+'，已全部用完':'已用掉 '+bsFmt(a)+u):'已买来 '+bsFmt(a)+u;
    update(function(s){return bsWith(s,function(l){return l.map(function(i){return i.id===it.id?Object.assign({},i,{qty:Math.max(0,bsR(i.qty+sign*a))}):i})})}).catch(function(){
      ui.note='保存失败，数量没有改变，请重试';ui.noteBad=true;redraw();
    });
  };
  const del=function(){
    update(function(s){return bsWith(s,function(l){return l.filter(function(i){return i.id!==it.id})})}).then(function(){
      ui.view='list';ui.detailId=null;ui.confirmDel=false;ui.note='';redraw();
    },function(){
      ui.note='删除失败，请重试';ui.noteBad=true;ui.confirmDel=false;redraw();
    });
  };

  const bigKids=[el('b',{},bsFmt(it.qty))];
  if(u)bigKids.push(el('i',{},u));
  const left=el('div',{class:'dq'},
    el('div',{class:'big'},...bigKids),
    el('div',{class:'st'+(low?' low':'')},(low?'⚠ 快用完':'✓ 够用')+'，低于 '+bsFmt(it.low)+u+' 时提醒'));

  const amt=el('input',{class:'inp',type:'number',min:'0',step:'any',inputmode:'decimal',value:ui.amount,'aria-label':'这次的数量',oninput:function(e){ui.amount=e.target.value}});
  const right=el('div',{class:'da'},
    el('label',{class:'fld'},el('span',{class:'fl'},'这次数量'+(u?'（'+u+'）':'')),amt),
    el('div',{class:'two'},
      el('button',{class:'btn',type:'button',onclick:function(){apply(-1)}},'− 用掉'),
      el('button',{class:'btn pri',type:'button',onclick:function(){apply(1)}},'+ 买来')),
    el('div',{class:'note'+(ui.noteBad?' bad':''),role:'status'},ui.note?((ui.noteBad?'⚠ ':'✓ ')+ui.note):''));

  const foot=ui.confirmDel
    ?el('div',{class:'ft wrap'},
        el('div',{class:'ask'},'确定删除「'+it.name+'」？'),
        el('button',{class:'btn',type:'button',onclick:function(){ui.confirmDel=false;redraw();}},'取消'),
        el('button',{class:'btn pri',type:'button',onclick:del},'确认删除'))
    :el('div',{class:'ft'},
        el('button',{class:'btn',type:'button',onclick:function(){bsOpenForm(c,it,'')}},'编辑'),
        el('button',{class:'btn',type:'button',onclick:function(){ui.confirmDel=true;redraw();}},'删除'));

  return el('div',{class:'pane'},
    el('div',{class:'hd'},el('button',{class:'btn ico',type:'button','aria-label':'返回列表',onclick:back},'←'),el('div',{class:'ttl',title:it.name},it.name)),
    el('div',{class:'dbody'},left,right),
    foot);
}

const RUNTIME_BUILD='v50-r22-theme-20261102';
const INFRA_CSS=`:host{display:block;width:100%;height:100%}*{box-sizing:border-box}.card{width:100%;height:100%;position:relative;container:card / size;min-width:0;min-height:0;overflow:auto}button,input,textarea,select{font:inherit}button{cursor:pointer;touch-action:manipulation}.infra-panel{position:absolute;inset:0;z-index:100;display:grid;grid-template-rows:auto minmax(0,1fr) auto;gap:10px;padding:12px;background:var(--panel-paper);color:var(--ink);overflow:hidden;font:13px/1.4 system-ui}.infra-head{display:flex;align-items:center;justify-content:space-between;gap:8px}.infra-content{overflow:auto;min-height:0}.infra-actions{display:flex;gap:6px;flex-wrap:wrap}.infra-panel button{border:1px solid var(--line);border-radius:8px;padding:7px 10px;background:var(--button-paper);color:inherit}.infra-panel button[data-primary]{background:var(--accent);color:var(--on-accent)}.infra-form{display:grid;gap:10px}.infra-form label{display:grid;gap:4px}.infra-form input:not([type=checkbox]),.infra-form textarea,.infra-form select{width:100%;min-width:0;padding:8px;border:1px solid var(--line);border-radius:7px;background:var(--panel-paper);color:inherit}.infra-error{color:var(--danger);font-size:12px}.infra-form textarea{min-height:65px}`;
export default class Card extends HTMLElement{
 constructor(){super();this.attachShadow({mode:'open'});this.state={};this.ui={};this.queue=Promise.resolve();this.epoch=0;this.pending=0;}
 set tabbitHost(h){this.host=h;if(this.isConnected)this.load();}
 connectedCallback(){if(this.host)this.load();}
 disconnectedCallback(){this.epoch++;this.stop();}
 destroy(){this.disconnectedCallback();}
